const form = $("Form - Screaming frog internal_html.csv upload").first().json;
return [
  {
    json: {
      name: String(form["What is the name of your website?"] ?? ""),
      description: String(
        form[
          "Can you provide a short description of your website? (in the language of the website)"
        ] ?? "",
      ),
      rows: $input.all().map((x) => x.json),
      mode: "direct",
    },
  },
];

function generate({ body }) {
  const { name, description, rows } = body;
  if (
    typeof name !== "string" ||
    !name.trim() ||
    typeof description !== "string" ||
    !Array.isArray(rows)
  )
    throw Error("Expected site name, description and CSV rows");
  const pick = (r, keys) =>
    keys.map((k) => r[k]).find((x) => x !== undefined && x !== null && String(x).trim() !== "") ??
    "";
  const lines = [];
  for (const r of rows) {
    const url = String(pick(r, ["Address", "Adresse", "Dirección", "Indirizzo"])),
      title = String(pick(r, ["Title 1", "Titre 1", "Titolo 1", "Título 1", "Titel 1"])),
      desc = String(pick(r, ["Meta Description 1", "Meta description 1"])),
      status = Number(
        pick(r, [
          "Status Code",
          "Code HTTP",
          "Status-Code",
          "Código de respuesta",
          "Codice di stato",
        ]),
      ),
      index = String(
        pick(r, [
          "Indexability",
          "Indexabilité",
          "Indicizzabilità",
          "Indexabilidad",
          "Indexierbarkeit",
        ]),
      ),
      type = String(
        pick(r, [
          "Content Type",
          "Type de contenu",
          "Tipo di contenuto",
          "Tipo de contenido",
          "Inhaltstyp",
        ]),
      );
    if (
      status !== 200 ||
      !["Indexable", "Indicizzabile", "Indexierbar"].includes(index) ||
      !type.includes("text/html") ||
      !url
    )
      continue;
    const clean = (x) => x.replace(/[\r\n]+/g, " ").trim();
    lines.push("- [" + clean(title) + "](" + clean(url) + ")" + (desc ? ": " + clean(desc) : ""));
  }
  return {
    content: "# " + name.trim() + "\n> " + description.trim() + "\n\n" + lines.join("\n"),
    count: lines.length,
  };
}

return { json: generate({ body: $json }) };
